import{c as a,Q as r,j as o,m as t}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Governing Evolving Memory in LLM Agents: Risks, Mechanisms, and the Stability and Safety Governed Memory (SSGM) Framework","description":"","frontmatter":{"url":"https://arxiv.org/abs/2603.11768","title":"Governing Evolving Memory in LLM Agents: Risks, Mechanisms, and the Stability and Safety Governed Memory (SSGM) Framework","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2603.11768,"authors":["Chingkwun Lam","Jiaxin Li","Lingfei Zhang","Kuo Zhao"],"domains":["cs.AI"],"html":"https://arxiv.org/html/2603.11768v1","pdf_path":"pdfs/2603.11768.pdf","published_date":"2026-03-12T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-03-12-governing-evolving-memory-ssgm-2603-11768.md","filePath":"research/papers/2026-03-12-governing-evolving-memory-ssgm-2603-11768.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-03-12-governing-evolving-memory-ssgm-2603-11768.md"};function i(s,e,l,m,c,d){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="governing-evolving-memory-in-llm-agents-risks-mechanisms-and-the-stability-and-safety-governed-memory-ssgm-framework" tabindex="-1">Governing Evolving Memory in LLM Agents: Risks, Mechanisms, and the Stability and Safety Governed Memory (SSGM) Framework <a class="header-anchor" href="#governing-evolving-memory-in-llm-agents-risks-mechanisms-and-the-stability-and-safety-governed-memory-ssgm-framework" aria-label="Permalink to &quot;Governing Evolving Memory in LLM Agents: Risks, Mechanisms, and the Stability and Safety Governed Memory (SSGM) Framework&quot;">​</a></h1><p><strong>Authors</strong>: Chingkwun Lam, Jiaxin Li, Lingfei Zhang, Kuo Zhao <strong>Published</strong>: March 12, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2603.11768" target="_blank" rel="noreferrer">https://arxiv.org/abs/2603.11768</a> · <a href="https://arxiv.org/html/2603.11768v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2603.11768 <strong>Categories</strong>: cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2603.11768" target="_blank" rel="noreferrer">research/papers/pdfs/2603.11768.pdf</a> (13 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Long-term memory has emerged as a foundational component of autonomous Large Language Model (LLM) agents, enabling continuous adaptation, lifelong multimodal learning, and sophisticated reasoning. However, as memory systems transition from static retrieval databases to dynamic, agentic mechanisms, critical concerns regarding memory governance, semantic drift, and privacy vulnerabilities have surfaced. While recent surveys have focused extensively on memory retrieval efficiency, they largely overlook the emergent risks of memory corruption in highly dynamic environments. To address these emerging challenges, we propose the Stability and Safety-Governed Memory (SSGM) framework, a conceptual governance architecture. SSGM decouples memory evolution from execution by enforcing consistency verification, temporal decay modeling, and dynamic access control prior to any memory consolidation. Through formal analysis and architectural decomposition, we show how SSGM can mitigate topology-induced knowledge leakage where sensitive contexts are solidified into long-term storage, and help prevent semantic drift where knowledge degrades through iterative summarization. Ultimately, this work provides a comprehensive taxonomy of memory corruption risks and establishes a robust governance paradigm for deploying safe, persistent, and reliable agentic memory systems.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 SSGM（Stability and Safety-Governed Memory）：一個概念性治理架構，將 memory evolution 與 execution 解耦，於任何 memory consolidation 之前強制 consistency verification、temporal decay modeling、dynamic access control。</li><li>提供 memory corruption 風險的完整 taxonomy，聚焦過往被忽略的「動態環境下記憶腐化」風險。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>形式化分析 + 架構分解顯示 SSGM 可緩解 topology-induced knowledge leakage（敏感脈絡被固化進長期儲存）。</li><li>可防止 semantic drift（知識在 iterative summarization 中退化）。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>文件未於 abstract 列明確 limitation；判斷弱點：明示為「conceptual」架構，缺端到端實證/量化；治理機制的延遲與成本未評估。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>「memory consolidation 前強制 consistency verification + access control」幾乎是 core.md APPLY「破壞性 gate」與 RECORD「整合門控非自動」的記憶版翻版——寫入長期記憶前須過閘。</li><li>「semantic drift through iterative summarization」精準命中 context-management 的 compact 風險：全量 rewrite → context collapse；本庫對策正是 delta hint。</li><li>「topology-induced knowledge leakage（敏感脈絡固化）」對應 security-hygiene 與 <code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md）的 Agent Input Security——敏感資料不應被無差別寫入持久記憶。⚠️ SSGM 仍屬概念框架，本庫已有的 hook/gate 是其精神的局部落地。</li></ul>',16)])])}const u=a(n,[["render",i]]);export{h as __pageData,u as default};
